//! Re-implementation of the subset of `tsl::hopscotch_map` used by test5,
//! backed by `std::collections::HashMap` (black-box equivalent behavior).

use std::collections::HashMap;
use std::hash::Hash;

/// A minimal ordered-agnostic key/value map mirroring the
/// `tsl::hopscotch_map` interface used by the test program.
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K: Eq + Hash, V> HopscotchMap<K, V> {
    /// Creates an empty map.
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Inserts a key/value pair. If the key already exists, the value is
    /// left unchanged (matching `std::map`-style `insert` semantics).
    pub fn insert(&mut self, key: K, value: V) {
        self.inner.entry(key).or_insert(value);
    }

    /// Erases the element with the given key, returning the number of
    /// elements removed (0 or 1), like `std::unordered_map::erase`.
    pub fn erase(&mut self, key: &K) -> usize {
        if self.inner.remove(key).is_some() {
            1
        } else {
            0
        }
    }

    /// Returns the number of elements in the map.
    pub fn size(&self) -> usize {
        self.inner.len()
    }
}

impl<K: Eq + Hash, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

