//! Rust port of /workspace/dataset/hopscotch-map/tests/test5.cpp
//!
//! Inserts `count` entries (i -> i*2) into a hopscotch-map equivalent,
//! erases every even key, then prints "<size> <removed>".

#[path = "src/hopscotch.rs"]
mod hopscotch;

use hopscotch::HopscotchMap;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 5;
    if args.len() > 1 && args[1] == "--a" {
        count = args[2].parse::<i32>().expect("invalid stoi argument");
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    for i in 0..count {
        map.insert(i, i * 2);
    }

    let mut removed: usize = 0;
    let mut i: i32 = 0;
    while i < count {
        removed += map.erase(&i);
        i += 2;
    }

    println!("{} {}", map.size(), removed);
}

